export function traceParamsAt(seconds){
 const t=clamp(seconds,0,1.1);let i=0;while(i+1<KO_TRACE.length&&KO_TRACE[i+1].t<t)i++;
 const a=KO_TRACE[i],b=KO_TRACE[Math.min(i+1,KO_TRACE.length-1)];
 const q=b.t===a.t?0:(t-a.t)/(b.t-a.t);
 return blendParams(a.p,b.p,q);
}

const angleMix=(a,b,q)=>a+Math.atan2(Math.sin(b-a),Math.cos(b-a))*q;
const handRadius=a=>Math.hypot(3.4*Math.sin(a),2.8*Math.cos(a));
function floorArmAngle(height){let lo=-Math.PI/2,hi=0;for(let n=0;n<36;n++){const a=(lo+hi)/2;if(height+38.5*Math.sin(a)<handRadius(a))lo=a;else hi=a;}return hi;}
function bodyFloorClearance(j){
 const sole=s=>{const h=j[s+'_heel'],to=j[s+'_toe'],a=j[s+'_ankle'],v=sub(to,h),l=Math.hypot(...v)||1;let n=[-v[1]/l,v[0]/l];if(n[0]*(a[0]-h[0])+n[1]*(a[1]-h[1])<0)n=n.map(x=>-x);return Math.min(h[1],to[1],to[1]+n[1]*2,a[1]+2,h[1]+n[1]*3.5,a[1]-2.4,j[s+'_knee'][1]-3.6);};
 const y=Math.min(j.head[1]-8,j.chest[1]-8.6,j.center[1]-7,...['support','strike'].map(sole));
 return y;
}
function bodyGround(j){const y=bodyFloorClearance(j);for(const p of Object.values(j))p[1]-=y;return j;}
function restArms(j,t){
 const q=smooth((t-.30)/.05);
 if(q===0)return ground(j);
 for(const s of ['near','far']){
  const sh=j[s+'_shoulder'],old=Math.atan2(j[s+'_elbow'][1]-sh[1],j[s+'_elbow'][0]-sh[0]);
  const floor=floorArmAngle(sh[1]);
  const intended=Math.atan2(j[s+'_hand'][1]-sh[1],Math.abs(j[s+'_hand'][0]-sh[0]));
  const target=angleMix(Math.max(intended,floor),floor,smooth((t-.72)/.38));
  const a=angleMix(old,target,q);
  for(const[part,len]of [['elbow',18],['wrist',35],['hand',38.5]])j[s+'_'+part]=add(sh,mul(vec(a),len));
 }
 return q<1?ground(j):j;
}
function fallenPoseCore(initial,seconds,{minX=-Infinity,maxX=Infinity}={},connectEntry=true){
 if(seconds<=0)return initial;
 const t=clamp(seconds,0,1.1),a=params(initial),p=traceParamsAt(t);
 p.sa=[a.sa[0]+p.sa[0],a.sa[1]+p.sa[1]];
 p.sn=a.sn;p.kn=a.kn;
 // Actual interrupted pose releases continuously; no restart at neutral.
 const release=smooth((t-.02)/.28);
 for(const side of ['near','far'])for(const part of ['u','f','h']){
  const k=side+part,first=KO_TRACE[0].p[k],branch=a[k]+Math.atan2(Math.sin(first-a[k]),Math.cos(first-a[k]));
  p[k]=a[k]+(branch+p[k]-first-a[k])*release;
 }
 let j=forward(p,[0,0]);
 const shoulderOffset=[(initial.near_shoulder[0]+initial.far_shoulder[0])/2-initial.chest[0],(initial.near_shoulder[1]+initial.far_shoulder[1])/2-initial.chest[1]],entry=1-smooth(t/.24);
 for(const side of ['near','far'])for(const part of ['shoulder','elbow','wrist','hand'])for(let axis=0;axis<2;axis++)j[side+'_'+part][axis]+=shoulderOffset[axis]*entry;
 if(connectEntry&&t<.26)j=entryPose(initial,j,p,smooth(t/.26),shoulderOffset.map(v=>v*entry));
 j=bodyGround(j);j=restArms(j,t);
 const xs=Object.values(j).map(p=>p[0]),shift=Math.max(0,minX-(Math.min(...xs)-8))-Math.max(0,(Math.max(...xs)+8)-maxX);
 if(shift)for(const p of Object.values(j))p[0]+=shift*smooth(t/.18);
 return j;
}
export const loserIndex=b=>b?.winner==='player'?1:b?.winner==='opponent'?0:null;
export const fallHeadTilt=seconds=>seconds<=0?0:-Math.PI/2*smooth(seconds/.72);

// R28 private BF alone consumes the SAME target clock before the planar entry.
export function fallenPose(initial,seconds,options={}){
 const j=fallenPoseCore(initial,seconds,options,true);
 if(options.pushkickTrace&&seconds>0&&seconds<.26){
  // Preserve airborne entry clearance, then join unchanged fall. Full-body
  // translation preserves every bone; only pushkick opts into this adaptation.
  const lift=Math.max(0,bodyFloorClearance(initial))*(1-smooth(seconds/.26));
  if(lift)for(const p of Object.values(j))p[1]+=lift;
 }
 return j;
}
export function backfistKOTarget(initial,seconds,options={}){return fallenPoseCore(initial,seconds,options,false);}
